    std::vector<uint32_t> byte_encoder_;
    std::map<uint32_t, uint8_t> byte_decoder_;

    mutable std::unordered_map<std::string, std::vector<std::string>> bpe_cache_;
    mutable std::mutex cache_mu_;
};

