8	// ---------------- I/O helpers ----------------
9	std::vector<std::string> BpeTokenizer::LoadVocab(const std::string& vocab_path) {
10	    std::ifstream ifs(vocab_path);
11	    if (!ifs.is_open()) {
12	        throw std::runtime_error("Failed to open vocab file: " + vocab_path);
13	    }
14	    std::vector<std::string> vocab;
15	    vocab.reserve(50000);
16	    std::string line;
17	    while (std::getline(ifs, line)) {
18	        if (!line.empty()) {
19	            if (line.back() == '\r') {
20	                line.pop_back(); // strip CR
21	            }
22	            vocab.push_back(line);
23	        }
24	    }
25	    return vocab;
26	}
27	
28	std::unordered_map<std::string, int> BpeTokenizer::BuildTokenToId(const std::vector<std::string>& id_to_token) {
29	    std::unordered_map<std::string, int> m;
30	    m.reserve(id_to_token.size() * 2);
31	    for (size_t i = 0; i < id_to_token.size(); ++i) {
32	        m.emplace(id_to_token[i], static_cast<int>(i));
33	    }
34	    return m;
35	}
36	
37	std::unordered_map<std::string, int> BpeTokenizer::LoadMergesRank(const std::string& merges_path) {
38	    std::ifstream ifs(merges_path);
39	    if (!ifs.is_open()) {
40	        throw std::runtime_error("Failed to open merges file: " + merges_path);
41	    }
42	    std::unordered_map<std::string, int> merges;
43	    merges.reserve(50000);
44	    std::string line;
45	    int rank = 0;
46	    while (std::getline(ifs, line)) {
47	        if (line.empty() || line[0] == '#') continue;
48	        std::istringstream iss(line);
49	        std::string a, b;
50	        if (!(iss >> a >> b)) continue;
51	        merges.emplace(PairKey(a, b), rank++);
52	    }
53	    return merges;
54	}
55	
56	// ---------------- UTF-8 utilities ----------------
57	
58	bool BpeTokenizer::IsAsciiSpace(unsigned char c) {
59	    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
60	}
61	
62	bool BpeTokenizer::IsUnicodeSpace(uint32_t cp) {
63	    if (cp <= 0x7F) return IsAsciiSpace(static_cast<unsigned char>(cp));
64	    switch (cp) {
65	        case 0x00A0: case 0x1680:
66	        case 0x2000: case 0x2001: case 0x2002: case 0x2003:
67	        case 0x2004: case 0x2005: case 0x2006: case 0x2007:
68	        case 0x2008: case 0x2009: case 0x200A:
69	        case 0x2028: case 0x2029:
70	        case 0x202F: case 0x205F: case 0x3000:
71	            return true;
72	        default:
73	            return false;
74	    }
75	}
76	
77	bool BpeTokenizer::NextUtf8(const std::string& s, size_t& i, uint32_t& cp, size_t& cp_len) {
78	    if (i >= s.size()) return false;
79	    unsigned char c0 = static_cast<unsigned char>(s[i]);
80	    if (c0 < 0x80) {
81	        cp = c0; cp_len = 1; ++i; return true;
82	    } else if ((c0 >> 5) == 0x6) {
83	        if (i + 1 >= s.size()) return false;
84	        unsigned char c1 = static_cast<unsigned char>(s[i+1]);
85	        if ((c1 & 0xC0) != 0x80) return false;
86	        cp = ((c0 & 0x1F) << 6) | (c1 & 0x3F);
87	        cp_len = 2; i += 2; return true;
88	    } else if ((c0 >> 4) == 0xE) {
89	        if (i + 2 >= s.size()) return false;
90	        unsigned char c1 = static_cast<unsigned char>(s[i+1]);
91	        unsigned char c2 = static_cast<unsigned char>(s[i+2]);
92	        if (((c1 & 0xC0) != 0x80) || ((c2 & 0xC0) != 0x80)) return false;
93	        cp = ((c0 & 0x0F) << 12) |
94	             ((c1 & 0x3F) << 6) |
95	             (c2 & 0x3F);
96	        cp_len = 3; i += 3; return true;
97	    } else if ((c0 >> 3) == 0x1E) {
98	        if (i + 3 >= s.size()) return false;
99	        unsigned char c1 = static_cast<unsigned char>(s[i+1]);
100	        unsigned char c2 = static_cast<unsigned char>(s[i+2]);
101	        unsigned char c3 = static_cast<unsigned char>(s[i+3]);
102	        if (((c1 & 0xC0) != 0x80) || ((c2 & 0xC0) != 0x80) || ((c3 & 0xC0) != 0x80)) return false;
103	        cp = ((c0 & 0x07) << 18) |
104	             ((c1 & 0x3F) << 12) |
105	             ((c2 & 0x3F) << 6) |
106	             (c3 & 0x3F);
107	        cp_len = 4; i += 4; return true;
108	    }
109	    return false;
110	}
111	
112	std::vector<std::string> BpeTokenizer::Utf8Chars(const std::string& s) {
113	    std::vector<std::string> chars;
114	    chars.reserve(s.size());
115	    size_t i = 0;
116	    while (i < s.size()) {
117	        size_t start = i;
118	        uint32_t cp; size_t cp_len;
119	        if (!NextUtf8(s, i, cp, cp_len)) break;
120	        chars.emplace_back(s.substr(start, i - start));
121	    }
122	    return chars;
123	}
124	
125	// ---------------- Byte Encoder/Decoder (New Logic) ----------------
126	
127	void BpeTokenizer::InitByteMaps() {
128	    byte_encoder_.resize(256, 0);
129	    byte_decoder_.clear();
130	
131	    // Logic based on GPT-2 byte encoder (map printable chars to themselves, others to 256+)
132	    auto is_printable = [](int b) {
133	        return (b >= '!' && b <= '~')     // '!' to '~'
134	                || (b >= 161 && b <= 172)  // '¡' to '¬'
135	                || (b >= 174 && b <= 255); // '®' to 'ÿ'
136	    };
137	
138	    int n = 0;
139	    for (int b = 0; b < 256; ++b) {
140	        if (is_printable(b)) {
141	            byte_encoder_[b] = static_cast<uint32_t>(b);
142	        } else {
143	            byte_encoder_[b] = static_cast<uint32_t>(256 + n);
144	            n++;
145	        }
146	        // Build decoder map
147	        byte_decoder_[byte_encoder_[b]] = static_cast<uint8_t>(b);
148	    }
149	}
150	
151	std::string BpeTokenizer::ByteEncode(const std::string& text) const {
152	    std::string out;
153	    out.reserve(text.size() * 2);
154	
155	    for (unsigned char b : text) {
156	        uint32_t cp = byte_encoder_[b];
157	        // Append cp as UTF-8
158	        if (cp < 0x80) {
159	            out += static_cast<char>(cp);
160	        } else if (cp < 0x800) {
161	            out += static_cast<char>((cp >> 6) | 0xC0);
162	            out += static_cast<char>((cp & 0x3F) | 0x80);
163	        } else if (cp < 0x10000) {
164	            out += static_cast<char>((cp >> 12) | 0xE0);
165	            out += static_cast<char>(((cp >> 6) & 0x3F) | 0x80);
166	            out += static_cast<char>((cp & 0x3F) | 0x80);
167	        } else {
168	            out += static_cast<char>((cp >> 18) | 0xF0);
169	            out += static_cast<char>(((cp >> 12) & 0x3F) | 0x80);
170	            out += static_cast<char>(((cp >> 6) & 0x3F) | 0x80);
171	            out += static_cast<char>((cp & 0x3F) | 0x80);
172	        }
173	    }
174	    return out;
175	}
176	
177	std::string BpeTokenizer::ByteDecode(const std::string& text) const {
178	    std::string out;
179	    out.reserve(text.size());
180	    size_t i = 0;
181	    uint32_t cp; size_t len;
182	    while (i < text.size()) {
183	        if (!NextUtf8(text, i, cp, len)) break;
184	
185	        auto it = byte_decoder_.find(cp);
186	        if (it != byte_decoder_.end()) {
187	            out += static_cast<char>(it->second);
188	        } else {
189	            // If codepoint is not in byte map, usually we ignore it or keep it
190	            // if it's part of a special token that wasn't filtered.
191	            // Here we ignore unmapped chars to ensure pure byte restoration.
192	        }
193	    }
194	    return out;
195	}
196	
197	// ---------------- Pretokenizer ----------------
198	std::vector<std::string> BpeTokenizer::PretokenizeSentencePiece(const std::string& text) {
199	    static const std::string ws_mark = "▁";
200	    std::vector<std::string> out;
201	    std::string curr;
202	    curr.reserve(text.size());
203	
204	    size_t i = 0;
205	    while (i < text.size()) {
206	        uint32_t cp; size_t len;
207	        if (!NextUtf8(text, i, cp, len)) break;
208	        if (IsUnicodeSpace(cp)) {
209	            if (!curr.empty()) {
210	                out.push_back(ws_mark + curr);
211	                curr.clear();
212	            }
213	        } else {
214	            curr.append(text, i - len, len);
215	        }
216	    }
217	    if (!curr.empty()) {
218	        out.push_back(ws_mark + curr);
219	    }
220	    return out;
221	}
222	
223	// ---------------- BPE core ----------------
224	
225	std::string BpeTokenizer::PairKey(const std::string& a, const std::string& b) {
226	    std::string key;
227	    key.reserve(a.size() + 1 + b.size());
228	    key.append(a);
229	    key.push_back('\t');
230	    key.append(b);
231	    return key;
232	}
233	
234	const std::vector<std::string>& BpeTokenizer::BpeForPieceCached(const std::string& piece) const {
235	    {
236	        std::lock_guard<std::mutex> g(cache_mu_);
237	        auto it = bpe_cache_.find(piece);
238	        if (it != bpe_cache_.end()) return it->second;
239	    }
240	    auto tokens = BpeForPiece(piece);
241	    {
242	        std::lock_guard<std::mutex> g(cache_mu_);
243	        auto [it, _] = bpe_cache_.emplace(piece, std::move(tokens));
244	        return it->second;
245	    }
246	}
247	
248	std::vector<std::string> BpeTokenizer::BpeForPiece(const std::string& piece) const {
249	    std::vector<std::string> symbols = Utf8Chars(piece);
250	    if (symbols.size() <= 1) return symbols;
251	
252	    while (symbols.size() >= 2) {
253	        int best_rank = std::numeric_limits<int>::max();
254	        int best_i = -1;
255	
256	        for (int i = 0; i + 1 < static_cast<int>(symbols.size()); ++i) {
257	            std::string key = PairKey(symbols[i], symbols[i + 1]);
258	            auto it = merges_rank_.find(key);
259	            if (it != merges_rank_.end()) {
260	                int r = it->second;
261	                if (r < best_rank) {
262	                    best_rank = r;
263	                    best_i = i;
264	                }
265	            }
266	        }
267	        if (best_i < 0) break;
268	
269	        symbols[best_i] += symbols[best_i + 1];
270	        symbols.erase(symbols.begin() + best_i + 1);
271	    }
272	    return symbols;
273	}
274	
275	void BpeTokenizer::TokensToIds(const std::vector<std::string>& tokens, std::vector<int>& out) const {
276	    for (const auto& t : tokens) {
277	        auto it = token_to_id_.find(t);
278	        if (it != token_to_id_.end()) {
279	            out.push_back(it->second);
280	        } else if (fallback_to_chars_) {
281	            auto chars = Utf8Chars(t);
282	            for (const auto& ch : chars) {
283	                auto it2 = token_to_id_.find(ch);
284	                if (it2 != token_to_id_.end()) {
285	                    out.push_back(it2->second);
286	                } else if (special_ids_.unk_id >= 0) {
287	                    out.push_back(special_ids_.unk_id);
288	                }
289	            }
290	        } else if (special_ids_.unk_id >= 0) {
291	            out.push_back(special_ids_.unk_id);
292	        }
293	    }
294	}
295	
296	// ---------------- Move semantics ----------------
297	BpeTokenizer::BpeTokenizer(BpeTokenizer&& other) noexcept
298	    : id_to_token_(std::move(other.id_to_token_)),
299	      token_to_id_(std::move(other.token_to_id_)),
300	      merges_rank_(std::move(other.merges_rank_)),
301	      special_ids_(other.special_ids_),
302	      fallback_to_chars_(other.fallback_to_chars_),
303	      additional_special_tokens_(std::move(other.additional_special_tokens_)),
304	      additional_special_token_ids_(std::move(other.additional_special_token_ids_)),
305	      additional_special_token_to_id_(std::move(other.additional_special_token_to_id_)),
306	      additional_special_id_set_(std::move(other.additional_special_id_set_)),
307	      use_byte_encoder_(other.use_byte_encoder_),
308	      byte_encoder_(std::move(other.byte_encoder_)),
309	      byte_decoder_(std::move(other.byte_decoder_)) {
310	    // 迁移缓存（为安全起见加锁）
311	    std::lock_guard<std::mutex> lk(other.cache_mu_);
312	    bpe_cache_ = std::move(other.bpe_cache_);
313	    // cache_mu_ 自身是新构造的 mutex
314	}
315	
316	BpeTokenizer& BpeTokenizer::operator=(BpeTokenizer&& other) noexcept {
317	    if (this != &other) {
318	        // 同时锁两边，避免数据竞争
319	        std::scoped_lock lk(cache_mu_, other.cache_mu_);
320	        id_to_token_ = std::move(other.id_to_token_);
321	        token_to_id_ = std::move(other.token_to_id_);
322	        merges_rank_ = std::move(other.merges_rank_);
323	        special_ids_ = other.special_ids_;
324	        fallback_to_chars_ = other.fallback_to_chars_;
325	        additional_special_tokens_ = std::move(other.additional_special_tokens_);
326	        additional_special_token_ids_ = std::move(other.additional_special_token_ids_);
327	        additional_special_token_to_id_ = std::move(other.additional_special_token_to_id_);
328	        additional_special_id_set_ = std::move(other.additional_special_id_set_);
329	        use_byte_encoder_ = other.use_byte_encoder_;
330	        byte_encoder_ = std::move(other.byte_encoder_);
331	        byte_decoder_ = std::move(other.byte_decoder_);
332	        bpe_cache_ = std::move(other.bpe_cache_);
333	        // cache_mu_ 仍为当前对象自己的 mutex
334	    }
335	    return *this;
336	}
337	
338	// ---------------- Public APIs ----------------
339	BpeTokenizer BpeTokenizer::LoadFromFiles(const std::string& vocab_path,
340	                                         const std::string& merges_path,
341	                                         const SpecialTokensConfig& spec,
342	                                         bool add_special_if_missing,
343	                                         bool fallback_to_chars,
344	                                         bool use_byte_encoder) {
345	    BpeTokenizer tok;
346	    tok.id_to_token_ = LoadVocab(vocab_path);
347	    if (tok.id_to_token_.empty()) {
348	        throw std::runtime_error("Vocab is empty: " + vocab_path);
349	    }
