431	std::vector<int> BpeTokenizer::encode(const std::string& text,
432	                                      bool add_bos,
433	                                      bool add_eos,
434	                                      bool add_cls,
435	                                      bool add_sep) const {
436	    std::vector<int> ids;
437	    ids.reserve(text.size() / 2 + 8);
438	
439	    if (add_cls && special_ids_.cls_id >= 0) ids.push_back(special_ids_.cls_id);
440	    if (add_bos && special_ids_.bos_id >= 0) ids.push_back(special_ids_.bos_id);
441	
442	    // 先在原始串中按子串匹配 additional_special_tokens；
443	    // 命中时：
444	    //   1) flush 之前累积的普通文本（走 SentencePiece+BPE）
445	    //   2) 直接输出 special id
446	    std::string buffer;
447	    buffer.reserve(text.size());
448	
449	    auto flush_buffer = [&]() {
450	        if (buffer.empty()) return;
451	
452	        if (use_byte_encoder_) {
453	            // Mode 2: Byte-Level Encoding
454	            // Encode raw bytes to mapped unicode chars
455	            std::string encoded_s = ByteEncode(buffer);
456	            // Perform BPE on the entire encoded string
457	            const auto& toks = BpeForPieceCached(encoded_s);
458	            TokensToIds(toks, ids);
459	        } else {
460	            auto pieces = PretokenizeSentencePiece(buffer);
461	            for (const auto& p : pieces) {
462	                const auto& toks = BpeForPieceCached(p);
463	                TokensToIds(toks, ids);
464	            }
465	        }
466	        buffer.clear();
467	    };
468	
469	    size_t i = 0;
470	    const size_t n = text.size();
471	    while (i < n) {
472	        int matched_index = -1;
473	        size_t matched_len = 0;
474	
475	        // longest match：若多个 special token 共享前缀，选择更长的那个
476	        if (!additional_special_tokens_.empty()) {
477	            for (size_t k = 0; k < additional_special_tokens_.size(); ++k) {
478	                const std::string& sp = additional_special_tokens_[k];
479	                if (sp.empty()) continue;
480	                size_t len = sp.size();
481	                if (len <= matched_len) continue;
482	                if (i + len <= n && text.compare(i, len, sp) == 0) {
483	                    matched_index = static_cast<int>(k);
484	                    matched_len = len;
485	                }
486	            }
487	        }
488	
489	        if (matched_index >= 0) {
490	            flush_buffer();
491	            ids.push_back(additional_special_token_ids_[matched_index]);
492	            i += matched_len;
493	            continue;
494	        }
495	
496	        buffer.push_back(text[i]);
497	        ++i;
498	    }
499	
500	    flush_buffer();
501	
502	    if (add_sep && special_ids_.sep_id >= 0) ids.push_back(special_ids_.sep_id);
503	    if (add_eos && special_ids_.eos_id >= 0) ids.push_back(special_ids_.eos_id);
504	    return ids;
505	}
